commands.command:
set -eu
user=policyprobe
getent passwd "$user" >/dev/null 2>&1 && userdel -r "$user" >/dev/null 2>&1 || true
useradd -m -s /bin/sh "$user"
trap 'userdel -r policyprobe >/dev/null 2>&1 || true; unset CUR NEW' 0 1 2 3 15
CUR="Zz9!$(od -An -N8 -tx1 /dev/urandom | tr -d ' \n')"
printf '%s:%s\n' "$user" "$CUR" | chpasswd
export CUR
SHORT="Qq7!$(od -An -N2 -tx1 /dev/urandom | tr -d ' \n')"
export NEW="$SHORT"
printf 'TEST 1: rejecting a generated password shorter than 12 characters\n'
expect <<'EXPECT_EOF'
log_user 1
set timeout 10
spawn su - policyprobe -c /usr/bin/passwd
expect -re {current.*password:}
send -- "$env(CUR)\r"
expect -re {New.*password:}
send -- "$env(NEW)\r"
expect {
  -re {BAD PASSWORD:[REDACTED]]]} { puts "RESULT: short password rejected by PAM" }
  timeout { puts "RESULT: expected short-password rejection not observed"; exit 21 }
}
expect eof
set w [wait]
if {[lindex $w 3] == 0} { puts "RESULT: unexpected success"; exit 22 }
EXPECT_EOF
FEW=$(tr -dc 'a-z' </dev/urandom | head -c 16)
export NEW="$FEW"
printf '\nTEST 2: rejecting a generated 16-character password with only one class\n'
expect <<'EXPECT_EOF'
log_user 1
set timeout 10
spawn su - policyprobe -c /usr/bin/passwd
expect -re {current.*password:}
send -- "$env(CUR)\r"
expect -re {New.*password:}
send -- "$env(NEW)\r"
expect {
  -re {BAD PASSWORD:[REDACTED]]]} { puts "RESULT: insufficient character classes rejected by PAM" }
  timeout { puts "RESULT: expected character-class rejection not observed"; exit 31 }
}
expect eof
set w [wait]
if {[lindex $w 3] == 0} { puts "RESULT: unexpected success"; exit 32 }
EXPECT_EOF
STRONG="Qq7!$(od -An -N4 -tx1 /dev/urandom | tr -d ' \n')"
export NEW="$STRONG"
printf '\nTEST 3: accepting a generated 12-character password with four classes\n'
expect <<'EXPECT_EOF'
log_user 1
set timeout 10
spawn su - policyprobe -c /usr/bin/passwd
expect -re {current.*password:}
send -- "$env(CUR)\r"
expect -re {New.*password:}
send -- "$env(NEW)\r"
expect -re {Retype.*password:}
send -- "$env(NEW)\r"
expect {
  -re {password updated successfully} { puts "RESULT: compliant 12-character password accepted" }
  timeout { puts "RESULT: expected successful password change not observed"; exit 41 }
}
expect eof
set w [wait]
if {[lindex $w 3] != 0} { puts "RESULT: compliant password change exited nonzero"; exit 42 }
EXPECT_EOF
printf '\nAll live passwd policy tests passed; removing temporary test account.\n'
unset CUR NEW SHORT FEW STRONG
userdel -r "$user" >/dev/null 2>&1
trap - 0 1 2 3 15

