catch {expect eof}
catch {wait} w
if {!$rejected} { puts "RESULT: no PAM rejection observed"; exit 22 }
EXPECT_EOF
NEW=$(tr -dc 'a-z' </dev/urandom | head -c 16)
export NEW
printf '\nTEST 2: generated candidate length=%s classes=lowercase-only (must be rejected)\n' "${#NEW}"
expect <<'EXPECT_EOF'
