set timeout 10
spawn su - policyprobe -c /usr/bin/passwd
expect -re {current.*password:}
send -- "$env(CUR)\r"
expect -re {New.*password:}
send -- "$env(NEW)\r"
set rejected 0
expect {
  -re {BAD PASSWORD:[REDACTED]]]} { set rejected 1; puts "RESULT: single-class candidate rejected by PAM" }
  eof {}
  timeout { puts "RESULT: timed out awaiting policy decision"; exit 31 }
}
catch {expect eof}
catch {wait} w
if {!$rejected} { puts "RESULT: no PAM rejection observed"; exit 32 }
EXPECT_EOF
NEW="Qq7!$(od -An -N4 -tx1 /dev/urandom | tr -d ' \n')"
export NEW
printf '\nTEST 3: generated candidate length=%s classes=upper,lower,digit,other (must be accepted)\n' "${#NEW}"
expect <<'EXPECT_EOF'
log_user 1
set timeout 10
spawn su - policyprobe -c /usr/bin/passwd
expect -re {current.*password:}
send -- "$env(CUR)\r"
expect -re {New.*password:}
send -- "$env(NEW)\r"
expect -re {Retype.*password:}
send -- "$env(NEW)\r"
set accepted 0
expect {
  -re {password updated successfully} { set accepted 1; puts "RESULT: compliant 12-character candidate accepted" }
  eof {}
  timeout { puts "RESULT: timed out awaiting password update"; exit 41 }
}
catch {expect eof}
catch {wait} w
if {!$accepted} { puts "RESULT: compliant candidate was not accepted"; exit 42 }
EXPECT_EOF
printf '\nAll live passwd policy tests passed; removing temporary test account.\n'
unset CUR NEW
userdel -r "$user" >/dev/null 2>&1
trap - 0 1 2 3 15

